  #[test]
  fn c067_invariant_phase_transition() {
      let dev = VersionPolicy::new("0.1.0").expect("valid");
      assert!(!dev.requires_semver_checks(), "0.x must NOT require semver-checks");
      assert!(dev.is_breaking_change_allowed(), "0.x allows breaking changes");

      let stable = VersionPolicy::new("1.0.0").expect("valid");
      assert!(stable.requires_semver_checks(), "1.0+ MUST require semver-checks");
      assert!(!stable.is_breaking_change_allowed(), "1.0+ must not allow breaking changes without MAJOR");

      // requires_semver_checks() returns true only for Stable
      let dev_high = VersionPolicy::new("0.999.999").expect("valid");
      assert!(!dev_high.requires_semver_checks(), "0.999.999 still Dev, no semver-checks");
